import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    if n == 0:
        print(-1)
        return
    arr = list(map(int, data[1:n+1]))
    if not arr:
        print(-1)
        return
    max_val = arr[0]
    for x in arr[1:]:
        if x > max_val:
            max_val = x
    print(max_val)

if __name__ == "__main__":
    main()
